def members(kind,numbers,parts='*',reason=None):
    return [dict(item_id=f'8227:TB:YM:C1:{kind}:{n}',parts=parts,
        membership_reason=reason or 'The requested source responses demonstrate the family decision; original connected parts, domains and source defects remain attached.')for n in numbers]
def fam(slug,title,decision,givens,constraints,representation,scaffold,alternatives,form,difficulty,distinction,ds,ms,pattern=None,exams=(),relation_reason=None):
    families.append(dict(family_id='8227:TEXTBOOK-FAMILY:'+slug,title=title,
        learner_decisions=decision,givens_and_unknowns=givens,constraints=constraints,
        representation_and_response=representation,scaffolding_and_connected_parts=scaffold,
        alternative_methods=alternatives,units_and_precision='Exact symbolic values unless a member explicitly asks rounding. Each member retains its original precision and answer records; no examination-wide rule is inferred from a key display.',
        answer_form=form,difficulty_progression=difficulty,distinction_basis=distinction,
        assessed_demand_ids=ds,member_specs=ms,
        examination_relation=dict(kind='structural branch'if pattern else'textbook-only',
            pattern_ids=['8227:FAMILY:'+pattern]if pattern else[],part_ids=list(exams),
            evidence_label='examination-observed (NSSCAS 8227), comparative link only'if pattern else'textbook-derived',
            reason=relation_reason or 'These are supporting textbook tasks. No matching examination structure has been established here; no examination frequency or standalone recipe selection is claimed.')))
